def distance(names, d, a, b):
    ia = ib = -1
    for i in range(len(names)):
        if names[i] == a: ia = i
        if names[i] == b: ib = i
    if ia == -1 or ib == -1:
        return None
    if ia < ib:
        ia, ib = ib, ia
    return d[ia][ib]
